double fn0(List<int> values) {
  if (values.isEmpty) return 0.0;
  int total = 0;
  for (final v in values) {
    int bits = v & 0xF;
    int count = 0;
    count += bits & 1;
    count += (bits >> 1) & 1;
    count += (bits >> 2) & 1;
    count += (bits >> 3) & 1;
    total += 4 - count;
  }
  return total / (values.length * 4);
}

