  var count = 0;
  var run = 0;
  for (var i = 0; i < input.length; i++) {
    if (input[i] == 'A') {
      run++;
    } else {
      if (run == n) count++;
      run = 0;
    }
  }
  if (run == n) count++;
  return count;
}

