List<int> fn0(List<int> values) {
  final indices = List<int>.generate(values.length, (i) => i);
  indices.sort((a, b) {
    final byValue = values[b].compareTo(values[a]);
    if (byValue != 0) return byValue;
    return a.compareTo(b);
  });
  return indices;
}
